SourceCode.Declaration:
//All entity contracts needs to be decorated with SysAppEntity attribute. 
//You also need to provide the entity key field which is commonly the recId field but can be any field in the contract
[SysAppEntity(tableStr(FMRental), methodStr(FMReservationPage, recId))]
class FMReservationPage
{
    protected int64 recIdInternal;

}

Method.Source:
[SysAppField(fieldStr(FMRental, RecId), "RecId")]
public int64 recId(int64 _value=recIdInternal)
{
    recIdInternal = _value;
    return recIdInternal;
}
